import{_ as a,o,c as t,a2 as s}from"./chunks/framework.BZO4qERu.js";const u=JSON.parse('{"title":"常见问题","description":"Tokeness Base URL、鉴权失败、余额不足、模型名、API Key 和工具接入常见问题。","frontmatter":{"title":"常见问题","description":"Tokeness Base URL、鉴权失败、余额不足、模型名、API Key 和工具接入常见问题。"},"headers":[],"relativePath":"faq.md","filePath":"faq.md","lastUpdated":1781353635000}'),r={name:"faq.md"};function d(n,e,i,l,h,c){return o(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h1><h2 id="tokeness-是什么" tabindex="-1">Tokeness 是什么？ <a class="header-anchor" href="#tokeness-是什么" aria-label="Permalink to &quot;Tokeness 是什么？&quot;">​</a></h2><p>Tokeness 是 AI API 网关。你用一个 API Key 调用不同模型，并在控制台查看余额、日志和用量。</p><h2 id="base-url-应该填什么" tabindex="-1">Base URL 应该填什么？ <a class="header-anchor" href="#base-url-应该填什么" aria-label="Permalink to &quot;Base URL 应该填什么？&quot;">​</a></h2><p>所有接入页统一填写：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://n.tokeness.io/v1</span></span></code></pre></div><p>如果某个客户端把字段拆成 Base URL、Endpoint、Host 或 Service URL，请优先把这个完整地址填到支持完整路径的字段里。不要自己删掉 <code>/v1</code>。</p><h2 id="为什么调用提示鉴权失败" tabindex="-1">为什么调用提示鉴权失败？ <a class="header-anchor" href="#为什么调用提示鉴权失败" aria-label="Permalink to &quot;为什么调用提示鉴权失败？&quot;">​</a></h2><p>常见原因包括 Key 复制不完整、请求头没有使用 <code>Bearer</code>、Key 被停用、环境变量未生效。</p><h2 id="为什么提示余额不足" tabindex="-1">为什么提示余额不足？ <a class="header-anchor" href="#为什么提示余额不足" aria-label="Permalink to &quot;为什么提示余额不足？&quot;">​</a></h2><p>Tokeness 采用预充值模式。请检查钱包余额，以及当前 API Key 是否设置了额度上限。</p><h2 id="模型名从哪里复制" tabindex="-1">模型名从哪里复制？ <a class="header-anchor" href="#模型名从哪里复制" aria-label="Permalink to &quot;模型名从哪里复制？&quot;">​</a></h2><p>从 Tokeness 控制台或模型广场复制。模型名需要保持大小写、连字符和版本号一致。</p><p>第一次接入时，先复制一个可用模型名，再回到教程里替换 <code>YOUR_MODEL_NAME</code>。</p><h2 id="能不能共用一个-key" tabindex="-1">能不能共用一个 Key？ <a class="header-anchor" href="#能不能共用一个-key" aria-label="Permalink to &quot;能不能共用一个 Key？&quot;">​</a></h2><p>技术上可以。开发、生产、客户项目、自动化任务使用不同 Key，便于限额和排查。</p><h2 id="支持哪些工具" tabindex="-1">支持哪些工具？ <a class="header-anchor" href="#支持哪些工具" aria-label="Permalink to &quot;支持哪些工具？&quot;">​</a></h2><p>支持自定义 OpenAI 兼容 Base URL 的工具，可以按本文档接入。本文档提供 Cherry Studio、Claude Code、VS Code Claude Code 插件、Cline、Dify、n8n、OpenClaw、OpenCode、Cursor、Codex CLI 的配置参考。</p><h2 id="claude-code-安装后命令不存在怎么办" tabindex="-1">Claude Code 安装后命令不存在怎么办？ <a class="header-anchor" href="#claude-code-安装后命令不存在怎么办" aria-label="Permalink to &quot;Claude Code 安装后命令不存在怎么办？&quot;">​</a></h2><p>先确认 Node.js 和 npm 已安装，并重启终端。如果是在 Windows 上使用 Claude Code，使用 PowerShell、WSL2 或工具官方推荐的 shell 环境。</p><h2 id="连接-ai-编程工具时报-401-怎么办" tabindex="-1">连接 AI 编程工具时报 401 怎么办？ <a class="header-anchor" href="#连接-ai-编程工具时报-401-怎么办" aria-label="Permalink to &quot;连接 AI 编程工具时报 401 怎么办？&quot;">​</a></h2><p>检查工具配置中的 API Key、Base URL、模型名和协议类型。OpenAI 兼容接入使用 <code>https://n.tokeness.io/v1</code>，请求头使用 <code>Authorization: Bearer &lt;API Key&gt;</code>。</p><h2 id="代码示例里的-your-model-name-是什么" tabindex="-1">代码示例里的 <code>YOUR_MODEL_NAME</code> 是什么？ <a class="header-anchor" href="#代码示例里的-your-model-name-是什么" aria-label="Permalink to &quot;代码示例里的 `YOUR_MODEL_NAME` 是什么？&quot;">​</a></h2><p>它不是固定模型名。请到模型广场复制实际模型名后替换。</p>',24)])])}const b=a(r,[["render",d]]);export{u as __pageData,b as default};
